verus! {
    // Verus program to solve the temperature string output problem.
    //
    // Given a temperature x in i8 limited to [-40, 40], return a Vec<u8> encoding
    // ASCII chars according to:
    //   if x >= 30, return b"Yes\n"
    //   else return b"No\n"
    //
    // The output vector must have exactly the ASCII bytes specified and no extra.

    fn solve(x: i8) -> Vec<u8> {
        // Precondition: input x is within [-40, 40]
        requires(x >= -40 && x <= 40);
        ensures(
            // If x >= 30, output equals b"Yes\n" as bytes
            (x >= 30 && result == vec![b'Y', b'e', b's', b'\n']) ||
            // Otherwise, output equals b"No\n"
            (x < 30 && result == vec![b'N', b'o', b'\n'])
        );
        ensures({
            // The returned vector length matches exactly length of output string
            if x >= 30 { result.len() == 4 } else { result.len() == 3 }
        });

        if x >= 30 {
            vec![b'Y', b'e', b's', b'\n']
        } else {
            vec![b'N', b'o', b'\n']
        }
    }
}